// Example: burst handling in a rate limiter
function slidingWindowCounter(currentCount, windowStartTime, currentTime) {
  const windowSize = 60000; // 1 minute in milliseconds
  const maxRequests = 10;
  const burstCapacity = 2;

  // Calculate elapsed time in window
  const elapsed = currentTime - windowStartTime;
  const timeRatio = elapsed / windowSize;

  // Allow burst capacity at window start, then reduce gradually
  const effectiveMax = maxRequests + burstCapacity * (1 - timeRatio);

  return currentCount <= effectiveMax;
}

