  // Calculate adjusted limit based on load
  const adjustedLimit = Math.floor(maxCapacity * (1 - systemLoad));

  // Determine if throttling is needed
  const shouldThrottle = currentHits > adjustedLimit;

  return { adjustedLimit, shouldThrottle };
}

